package com.grifplot.libros;
import java.io.*;import java.net.*;import java.util.*;import java.util.zip.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Bounded, signature-checked image downloads, with link fallback for every failure. */
final class ImagePack {
 static final class Item {String url,source,title,original="",google="",stable="";Item(String u,String s,String t){url=u;source=s;title=t;if(googlePreview(u))google=u;else original=u;}String key(){return !stable.isEmpty()?stable:!google.isEmpty()?google:url.isEmpty()?source:url;}}
 static boolean googlePreview(String value){try{String h=new URL(value).getHost().toLowerCase(Locale.ROOT);return h.equals("gstatic.com")||h.endsWith(".gstatic.com")||h.equals("googleusercontent.com")||h.endsWith(".googleusercontent.com");}catch(Exception e){return false;}}
 interface Progress {void update(int done,int total);boolean cancelled();default void phase(String message){}default void bytes(long count,long total){}default String dimensions(File file){return "";}}
 static final class Result{File file;int downloaded,failed,originals,previews;Result(File f,int d,int e,int o,int p){file=f;downloaded=d;failed=e;originals=o;previews=p;}}
 static URL publicUrl(String value)throws IOException {URL url=new URL(value);if(!"https".equalsIgnoreCase(url.getProtocol())||url.getUserInfo()!=null||(url.getPort()!=-1&&url.getPort()!=443))throw new IOException("Enlace no público o sin HTTPS");for(InetAddress ip:InetAddress.getAllByName(url.getHost()))if(ip.isAnyLocalAddress()||ip.isLoopbackAddress()||ip.isLinkLocalAddress()||ip.isSiteLocalAddress()||ip.isMulticastAddress()||(ip.getAddress().length==16&&(ip.getAddress()[0]&254)==252))throw new IOException("Enlace de red privada");return url;}
 static String extension(byte[] b){if(b.length>=8&&b[0]==(byte)137&&b[1]==80&&b[2]==78&&b[3]==71&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10)return "png";if(b.length>=3&&b[0]==(byte)255&&b[1]==(byte)216&&b[2]==(byte)255)return "jpg";if(b.length>=6&&(new String(b,0,6,java.nio.charset.StandardCharsets.US_ASCII).equals("GIF87a")||new String(b,0,6,java.nio.charset.StandardCharsets.US_ASCII).equals("GIF89a")))return "gif";if(b.length>=12&&new String(b,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")&&new String(b,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WEBP"))return "webp";return null;}
 static final class Choice {String ext,url,note;boolean original;Choice(String e,String u,String n,boolean o){ext=e;url=u;note=n;original=o;}}
 static Choice choose(Item item,File file,String ua,Progress progress,long remaining)throws IOException {
  String reason="No se encontró un enlace original";Set<String> tried=new HashSet<>();
  if(!item.original.isEmpty()){tried.add(item.original);try{return new Choice(download(item.original,file,ua,progress,Math.min(52428800L,remaining)),item.original,"Archivo de la fuente sin reducir ni recomprimir",true);}catch(IOException e){if(progress.cancelled())throw e;reason=e.getMessage();file.delete();}}
  progress.phase("Buscando original en la fuente…");for(String candidate:ImageOriginals.resolve(item,ua,progress)){if(tried.size()>=4||!tried.add(candidate))continue;try{return new Choice(download(candidate,file,ua,progress,Math.min(52428800L,remaining)),candidate,"Imagen identificada en la fuente, sin reducir ni recomprimir",true);}catch(IOException e){if(progress.cancelled())throw e;reason=e.getMessage();file.delete();}}
  if(progress.cancelled())throw new IOException("Cancelado");String backup=item.google.isEmpty()&&googlePreview(item.url)?item.url:item.google;
  if(!backup.isEmpty()){progress.phase("Original no disponible; descargando imagen de Google…");String ext;if(backup.startsWith("data:image/")){int comma=backup.indexOf(',');if(comma<0||!backup.substring(0,comma).endsWith(";base64")||backup.length()>350000)throw new IOException("Respaldo no compatible");byte[] bytes;try{bytes=java.util.Base64.getDecoder().decode(backup.substring(comma+1));}catch(IllegalArgumentException e){throw new IOException("Respaldo no válido");}ext=extension(bytes);if(ext==null||bytes.length>remaining)throw new IOException("Respaldo no válido o demasiado grande");try(OutputStream out=new FileOutputStream(file)){out.write(bytes);}}else ext=download(backup,file,ua,progress,Math.min(20971520L,remaining));return new Choice(ext,backup,"Puede ser pequeña para impresión. Original: "+reason,false);}
  throw new IOException("Original no disponible y sin respaldo descargable. "+reason);
 }
 static String printable(String url){return url.startsWith("data:")?"Imagen incorporada en Google, sin enlace directo":url;}
 static Result create(List<Item> items,File dir,String ua,Progress progress)throws IOException {
  dir.mkdirs();File[] old=dir.listFiles();if(old!=null)for(File f:old)if(System.currentTimeMillis()-f.lastModified()>86400000L)f.delete();File zip=new File(dir,"Imagenes-"+UUID.randomUUID()+".zip"),txt=new File(dir,"Enlaces-"+UUID.randomUUID()+".txt");
  StringBuilder all=new StringBuilder("Selección de imágenes\n\n"),pending=new StringBuilder("Enlaces pendientes para la PC\n\n"),quality=new StringBuilder("Calidad de imágenes. Los originales se guardan sin reducir ni recomprimir. Los respaldos de Google pueden ser pequeños para imprimir.\n\n");int ok=0,failed=0,originals=0,previews=0;long total=0;
  try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(zip))){for(int i=0;i<items.size();i++){if(progress.cancelled())throw new IOException("Cancelado");Item item=items.get(i);progress.phase("Imagen "+(i+1)+" de "+items.size()+": buscando original…");all.append(i+1).append(". ").append(item.title).append("\nOriginal: ").append(item.original).append("\nGoogle: ").append(printable(item.google)).append("\nFuente: ").append(item.source).append("\n\n");File temp=new File(dir,"imagen-"+UUID.randomUUID()+".part");try{Choice choice=null;try{if(total>=209715200L)throw new IOException("Paquete de 200 MB alcanzado");choice=choose(item,temp,ua,progress,209715200L-total);}catch(IOException e){if(progress.cancelled())throw e;failed++;pending.append(item.title).append("\nOriginal: ").append(item.original).append("\nGoogle: ").append(printable(item.google)).append("\nFuente: ").append(item.source).append("\nMotivo: ").append(e.getMessage()).append("\n\n");}if(choice!=null){total+=temp.length();String name=String.format(Locale.ROOT,"imagen-%03d.%s",i+1,choice.ext);out.putNextEntry(new ZipEntry(name));try(InputStream in=new FileInputStream(temp)){byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1){if(progress.cancelled())throw new IOException("Cancelado");out.write(buf,0,n);}}out.closeEntry();ok++;if(choice.original)originals++;else previews++;quality.append(name).append(" · ").append(item.title).append("\nTipo: ").append(choice.original?"ORIGINAL DE LA FUENTE":"IMAGEN DE GOOGLE · REVISAR PARA IMPRESIÓN").append("\nResolución: ").append(progress.dimensions(temp)).append("\nEnlace: ").append(printable(choice.url)).append("\n").append(choice.note).append("\n\n");if(!choice.original)pending.append(item.title).append("\nOriginal pendiente: ").append(item.original.isEmpty()?"No identificado":item.original).append("\nFuente: ").append(item.source).append("\n\n");}}finally{temp.delete();}progress.update(i+1,items.size());}
   entry(out,"enlaces-todas.txt",all);entry(out,"calidad-imagenes.txt",quality);if(failed>0||previews>0)entry(out,"enlaces-pendientes.txt",pending);
  }catch(IOException|RuntimeException e){zip.delete();txt.delete();throw e;}if(ok==0){zip.delete();try(OutputStream out=new FileOutputStream(txt)){out.write(pending.toString().getBytes("UTF-8"));}return new Result(txt,ok,failed,originals,previews);}return new Result(zip,ok,failed,originals,previews);
 }
 static void entry(ZipOutputStream out,String name,StringBuilder data)throws IOException{out.putNextEntry(new ZipEntry(name));out.write(data.toString().getBytes("UTF-8"));out.closeEntry();}
 static String download(String url,File file,String ua,Progress progress,long limit)throws IOException{HttpURLConnection c=null;try{URL address=publicUrl(url);for(int hop=0;hop<6;hop++){c=(HttpURLConnection)address.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("User-Agent",ua);c.setRequestProperty("Accept","image/png,image/jpeg,image/webp,image/gif,*/*;q=0.5");int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");if(location==null)throw new IOException("Redirección sin destino");URL next=publicUrl(new URL(address,location).toString());c.disconnect();c=null;address=next;continue;}if(status!=200)throw new IOException("La fuente no permite descargar (HTTP "+status+")");if(c.getContentLengthLong()>limit)throw new IOException("Imagen demasiado grande");try(InputStream in=c.getInputStream();OutputStream os=new FileOutputStream(file)){byte[] sig=new byte[12];int read=0,n;while(read<12&&(n=in.read(sig,read,12-read))!=-1)read+=n;String ext=extension(Arrays.copyOf(sig,read));if(ext==null)throw new IOException("El enlace no contiene una imagen PNG, JPG, GIF o WebP");os.write(sig,0,read);long total=read,last=0;byte[] buf=new byte[65536];while((n=in.read(buf))!=-1){if(progress.cancelled())throw new IOException("Cancelado");total+=n;if(total>limit)throw new IOException("Imagen demasiado grande");os.write(buf,0,n);if(System.currentTimeMillis()-last>300){progress.bytes(total,c.getContentLengthLong());last=System.currentTimeMillis();}}progress.bytes(total,c.getContentLengthLong());if(c.getContentLengthLong()>0&&total!=c.getContentLengthLong())throw new IOException("Descarga incompleta");return ext;}}throw new IOException("Demasiadas redirecciones");}finally{if(c!=null)c.disconnect();}}
}
